import { WebPlugin } from "./@capacitor_core.js";
//#region node_modules/@capacitor/app-launcher/dist/esm/web.js
var AppLauncherWeb = class extends WebPlugin {
	async canOpenUrl(_options) {
		return { value: true };
	}
	async openUrl(options) {
		window.open(options.url, "_blank");
		return { completed: true };
	}
};
//#endregion
export { AppLauncherWeb };
